import{_ as t,o as a,c as n,a5 as i}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"Rough Planning & Orientation","description":"","frontmatter":{"title":"Rough Planning & Orientation","cutting":"rough-planning"},"headers":[],"relativePath":"cutting/rough-planning.md","filePath":"cutting/rough-planning.md","lastUpdated":1789230763000}'),r={name:"cutting/rough-planning.md"};function o(l,e,s,h,c,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="rough-planning-orientation" tabindex="-1">Rough Planning &amp; Orientation <a class="header-anchor" href="#rough-planning-orientation" aria-label="Permalink to &quot;Rough Planning &amp; Orientation&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Cutting does not begin with choosing an attractive outline. The cutter first reads the rough: color zoning, fractures, inclusions, transparency, crystallographic direction, and possible optical phenomena. A plan balances weight retention, appearance, and durability, recording the table orientation, target outline, risks, and acceptable loss.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Inspect before sawing: clean, measure, and examine the rough under different lights and directions; mark fractures, inclusions, and color bands.</li><li>Prioritize orientation: with zoning, chatoyancy, asterism, or play of color, table direction controls how the effect is seen.</li><li>Make trade-offs explicit: retaining weight does not guarantee value; chasing weight can sacrifice brightness, symmetry, or durability.</li><li>Reserve a safety margin: avoid or reinforce corners, thin girdles, deep fractures, and stress concentrations in the design stage.</li><li>The final plan should explain why the stone was cut that way, not only describe its finished outline.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Cut</th><th>Note</th></tr></thead><tbody><tr><td>opal</td><td>orient the face toward the strongest play of color</td><td>prioritise the strongest color patches</td></tr><tr><td>star sapphire</td><td>align the dome with the intersecting silk</td><td>centre the star at the dome</td></tr></tbody></table><p><em>See the <a href="./intro.html">cutting overview</a>.</em></p>',8)])])}const u=t(r,[["render",o]]);export{p as __pageData,u as default};
